u1=U("intro","Introducing yourself and others","A2",
 "Give your name, role and one friendly detail. When you introduce others, say who they are and add something they share, so the conversation can start.",
 "নাম, কাজ আর একটা ছোট তথ্য বলুন। অন্যকে পরিচয় করানোর সময় দুজনের মিল আছে এমন কিছু বলুন, যাতে কথা শুরু হয়।",
 [("Yourself","Hi, I'm Rafi. I work in the marketing team. · I've just joined the company."),("Others","Rafi, this is Sara from Finance. · Sara, have you met Rafi?"),("Reply","Nice to meet you. · Nice to meet you too. · Good to see you again.")],
 [("Use 'I'm' or 'My name is' + first name. Don't say 'Myself Rafi'.","'Myself Rafi' ভুল; বলুন I'm Rafi।","Hi, I'm Rafi. I'm from Rajshahi."),
  ("Introduce others with 'This is…', not 'He is…'.","পরিচয় করাতে This is…।","Sara, this is Mr Ahmed, our new client."),
  ("'Nice to meet you' the first time; 'Nice to see you' after that.","প্রথম দেখায় meet, পরে see।","Nice to see you again, Karim!"),
  ("Add a detail to start talking.","কথা চালাতে একটা তথ্য যোগ করুন।","Sara, this is Rafi. He's from Rajshahi too."),
  ("Present perfect for new things: I've just joined.","সদ্য ঘটেছে বোঝাতে I've just…।","I've just started in the IT department.")],
 ["I'm…","this is…","have you met…?","nice to meet you","I've just joined"],
 [("Myself Rafi.","I'm Rafi.","'Myself' can't be a subject.","'আমি রাফি' বোঝাতে I'm Rafi।"),
  ("He is Sara from Finance.","This is Sara from Finance.","We introduce with 'This is'.","পরিচয়ে This is।"),
  ("I am working here since March.","I've been working here since March.","'Since' needs present perfect.","since থাকলে have been।")],
 [C("First day at a Dhaka office.","Hi, ___ Rafi. I've just joined the sales team.",["I'm","myself","me","my name"],"I'm","I'm + name."),
  C("Introducing a colleague.","Mr Lee, ___ my manager, Ms Rahman.",["this is","he is","she is","here is"],"this is","Introduce with 'this is'."),
  C("You met Karim last month. Today you see him again.","Karim! Nice to ___ you again.",["see","meet","know","look"],"see","Nice to see you again."),
  T("Reply to 'Nice to meet you.'","Nice to meet you ___.","also",["too"],"Nice to meet you too."),
  B("আমি রাজশাহী থেকে এসেছি, এটা আমার প্রথম চাকরি।",["I'm from Rajshahi, and this is my first job.","Myself from Rajshahi, my first job is this.","I am coming from Rajshahi, this is first job.","I'm from Rajshahi, and this my first job."],"I'm from Rajshahi, and this is my first job.","I'm from + place."),
  F("Pick the correct sentence.",["I am working here since 2024.","I work here since 2024.","I've been working here since 2024.","I have work here since 2024."],"I've been working here since 2024.","Since + present perfect continuous."),
  C("At a client event.","Sara, have you ___ Rafi? He's handling your account.",["met","meet","meeting","known"],"met","Have you met…?"),
  T("Very new in a job.","I've ___ joined the company, so I'm still learning.","adverb",["just"],"I've just joined = very recently.",True)])
u2=U("talk","Keeping a conversation going and ending it","B1",
 "Choose safe topics (work, weather, travel, food), ask follow-up questions, show you share things with 'So do I' or 'Neither do I', and close politely with a reason.",
 "নিরাপদ বিষয় বেছে নিন, পাল্টা প্রশ্ন করুন, So do I / Neither do I দিয়ে মিল দেখান, আর কারণ দেখিয়ে ভদ্রভাবে কথা শেষ করুন।",
 [("Follow up","Oh really? How long have you been there? · What was that like?"),("Agree","So do I. · So am I. · Neither do I. · Me too. · Me neither."),("End","Anyway, I'd better get back to work. · It was great talking to you.")],
 [("Avoid salary, age, marriage, religion with new people.","নতুন মানুষকে বেতন, বয়স, বিয়ে নিয়ে প্রশ্ন নয়।","How was your weekend? (not: How much do you earn?)"),
  ("Ask a follow-up question, not only yes/no.","শুধু হ্যাঁ/না নয়, পাল্টা প্রশ্ন করুন।","You went to Cox's Bazar? How was it?"),
  ("So + auxiliary + I for positive; Neither + auxiliary + I for negative.","হ্যাঁ বাক্যে So do I, না বাক্যে Neither do I।","I love biryani. So do I. / I don't drink coffee. Neither do I."),
  ("Match the auxiliary: am, do, have, can.","সহায়ক ক্রিয়া মিলিয়ে নিন।","I'm tired. So am I. / I've been to Sylhet. So have I."),
  ("End with a signal + reason + nice line.","শেষ করতে সংকেত, কারণ আর ভালো কথা।","Anyway, I'd better go. My meeting starts at three. It was lovely chatting!")],
 ["really?","so do I","neither do I","anyway","I'd better","it was great talking to you"],
 [("I like tea. Also me.","I like tea. Me too. / So do I.","'Also me' isn't English.","'আমিও' = Me too বা So do I।"),
  ("I don't like traffic. Me too.","I don't like traffic. Me neither. / Neither do I.","After a negative, use neither.","না বাক্যে Me neither।"),
  ("How much is your salary?","How are you finding the new job?","Salary is too personal for small talk.","বেতনের প্রশ্ন ব্যক্তিগত।")],
 [C("Colleague: 'I'm from Rajshahi.' You are too.","Oh, really? So ___ I!",["am","do","have","is"],"am","I'm → So am I."),
  C("Client: 'I don't eat spicy food.' You don't either.","___ do I.",["Neither","So","Either","Also"],"Neither","Negative → Neither do I."),
  F("Pick the best follow-up to 'I just got back from Singapore.'",["Ok.","Why?","Oh, nice! Was it for work or a holiday?","How much did it cost you?"],"Oh, nice! Was it for work or a holiday?","Interested, open follow-up."),
  F("Pick the safest small-talk question for a new client.",["Are you married?","How old are you?","How was your flight?","What is your religion?"],"How was your flight?","Travel is a safe topic."),
  T("Colleague: 'I've never been to Sylhet.' You haven't either.","Neither ___ I.","auxiliary",["have"],"I've never → Neither have I.",True),
  B("যাই হোক, আমাকে এখন কাজে ফিরতে হবে। কথা বলে ভালো লাগল।",["Anyway, I'd better get back to work. It was great talking to you.","Anyway, I must return my work. Talking was nice.","Ok bye, I have work.","Anyway, I'd better to get back to work. It was great to talking."],"Anyway, I'd better get back to work. It was great talking to you.","I'd better + base verb."),
  C("Ending a chat at a conference.","Well, I ___ let you go. Enjoy the rest of the event!",["should","must to","am","would"],"should","I should let you go = polite close."),
  C("Colleague: 'I can't stand Dhaka traffic.' You agree.","Neither ___ I. It took me two hours today.",["can","do","am","can't"],"can","Can't → Neither can I.",True),
  B("আমিও না।",["Me neither.","Me too not.","Also not me.","Me either not."],"Me neither.","Short negative agreement.")])
